"use client";

import * as React from "react";
import * as RechartsPrimitive from "recharts";
import { cn } from "@/lib/utils";

// ─── Chart config ────────────────────────────────────────────────────
export type ChartConfig = {
  [k: string]: {
    label?: React.ReactNode;
    icon?: React.ComponentType;
  } & (
    | { color?: string; theme?: never }
    | { color?: never; theme: Record<string, string> }
  );
};

const THEMES: Record<string, string> = { light: "", dark: ".dark" };

type ChartContextProps = { config: ChartConfig };

const ChartContext = React.createContext<ChartContextProps | null>(null);

function useChart() {
  const context = React.useContext(ChartContext);
  if (!context) {
    throw new Error("useChart must be used within a <ChartContainer />");
  }
  return context;
}

// ─── Container ───────────────────────────────────────────────────────
function ChartContainer({
  id,
  className,
  children,
  config,
  ...props
}: React.ComponentProps<"div"> & {
  config: ChartConfig;
  children: React.ComponentProps<
    typeof RechartsPrimitive.ResponsiveContainer
  >["children"];
}) {
  const uniqueId = React.useId();
  const chartId = `chart-${id || uniqueId.replace(/:/g, "")}`;

  return (
    <ChartContext.Provider value={{ config }}>
      <div
        data-slot="chart"
        data-chart={chartId}
        className={cn(
          "flex aspect-video justify-center text-xs font-[family-name:var(--pixel-font)]",
          "[&_.recharts-cartesian-axis-tick_text]:fill-muted-foreground",
          "[&_.recharts-cartesian-grid_line[stroke='#ccc']]:stroke-border/50",
          "[&_.recharts-curve.recharts-tooltip-cursor]:stroke-border",
          className
        )}
        {...props}
      >
        <ChartStyle id={chartId} config={config} />
        <RechartsPrimitive.ResponsiveContainer>
          {children}
        </RechartsPrimitive.ResponsiveContainer>
      </div>
    </ChartContext.Provider>
  );
}

const ChartStyle = ({
  id,
  config,
}: {
  id: string;
  config: ChartConfig;
}) => {
  const colorConfig = Object.entries(config).filter(
    // eslint-disable-next-line @typescript-eslint/no-unused-vars
    ([, config]) => config.theme || config.color
  );

  if (!colorConfig.length) {
    return null;
  }

  return (
    <style
      dangerouslySetInnerHTML={{
        __html: Object.entries(THEMES)
          .map(
            ([theme, prefix]) => `
${prefix} [data-chart=${id}] {
${colorConfig
  .map(([key, itemConfig]) => {
    const color =
      itemConfig.theme?.[theme as keyof typeof itemConfig.theme] ||
      itemConfig.color;
    return color ? `  --color-${key}: ${color};` : null;
  })
  .join("\n")}
}
`
          )
          .join("\n"),
      }}
    />
  );
};

// ─── Tooltip ─────────────────────────────────────────────────────────
// We deliberately build the tooltip content ourselves rather than
// forwarding recharts' generics, which changed shape in recharts v3.
function ChartTooltip({
  active,
  payload,
  label,
  className,
  indicator = "dot",
  hideLabel = false,
  hideIndicator = false,
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  formatter,
  color,
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  labelFormatter,
}: {
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  active?: boolean;
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  payload?: any[];
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  label?: any;
  className?: string;
  indicator?: "line" | "dot" | "dashed";
  hideLabel?: boolean;
  hideIndicator?: boolean;
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  formatter?: (value: any, name: any, item: any, index: number) => React.ReactNode;
  color?: string;
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  labelFormatter?: (label: any, payload: any[]) => React.ReactNode;
}) {
  const { config } = useChart();

  const tooltipLabel = React.useMemo(() => {
    if (hideLabel || !payload?.length) {
      return null;
    }

    const [item] = payload;
    const key = `${label || item.dataKey || item.name || "value"}`;
    const itemConfig = config[key];
    const value =
      !label && typeof label === "string"
        ? config[label as keyof typeof config]?.label || label
        : itemConfig?.label;

    if (labelFormatter) {
      return (
        <div className="text-xs">
          {labelFormatter(value, payload)}
        </div>
      );
    }

    if (!value) {
      return null;
    }

    return <div className="text-xs">{value}</div>;
  }, [hideLabel, payload, label, config, labelFormatter]);

  if (!active || !payload?.length) {
    return null;
  }

  const nestLabel = payload.length === 1 && indicator !== "dot";

  return (
    <div
      className={cn(
        "border-2 border-foreground bg-popover px-2.5 py-1.5 text-xs shadow-[var(--pixel-shadow)]",
        className
      )}
    >
      {!nestLabel ? tooltipLabel : null}
      <div className="grid gap-1.5">
        {payload.map((item, index) => {
          const key = `${item.name || item.dataKey || "value"}`;
          const itemConfig = config[key];
          const indicatorColor = color || item.payload?.fill || item.color;

          return (
            <div
              key={item.dataKey ?? index}
              className={cn(
                "flex w-full flex-wrap items-stretch gap-2 [&>svg]:h-2.5 [&>svg]:w-2.5 [&>svg]:text-muted-foreground",
                indicator === "dot" && "items-center"
              )}
            >
              {formatter && item?.value !== undefined && item.name ? (
                formatter(item.value, item.name, item, index)
              ) : (
                <>
                  {itemConfig?.icon ? (
                    <itemConfig.icon />
                  ) : (
                    !hideIndicator && (
                      <div
                        className={cn(
                          "shrink-0 border-2 border-foreground",
                          {
                            "h-2.5 w-2.5": indicator === "dot",
                            "w-1": indicator === "line",
                            "w-0 border-[1.5px] border-dashed bg-transparent":
                              indicator === "dashed",
                          }
                        )}
                        style={{
                          "--color-bg": indicatorColor,
                          "--color-border": indicatorColor,
                        } as React.CSSProperties}
                      />
                    )
                  )}
                  <div
                    className={cn(
                      "flex flex-1 justify-between leading-none",
                      nestLabel ? "items-end" : "items-center"
                    )}
                  >
                    <div className="grid gap-1.5">
                      {nestLabel ? tooltipLabel : null}
                      <span className="text-muted-foreground">
                        {itemConfig?.label || item.name}
                      </span>
                    </div>
                    {item.value !== undefined && item.value !== null && (
                      <span className="font-mono font-medium tabular-nums text-foreground">
                        {item.value.toLocaleString?.() ?? String(item.value)}
                      </span>
                    )}
                  </div>
                </>
              )}
            </div>
          );
        })}
      </div>
    </div>
  );
}

const ChartLegend = RechartsPrimitive.Legend;

// ─── Legend ──────────────────────────────────────────────────────────
function ChartLegendContent({
  className,
  hideIcon = false,
  payload,
  verticalAlign = "bottom",
  nameKey,
}: React.ComponentProps<"div"> &
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  { payload?: any[]; hideIcon?: boolean; nameKey?: string; verticalAlign?: "top" | "bottom" }) {
  const { config } = useChart();
  const items = payload ?? [];

  if (!items.length) {
    return null;
  }

  return (
    <div
      className={cn(
        "flex items-center justify-center gap-4",
        verticalAlign === "top" && "pb-3",
        className
      )}
    >
      {items
        .filter(
          // eslint-disable-next-line @typescript-eslint/no-explicit-any
          (item: any) => item.type !== "none"
        )
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        .map((item: any) => {
          const key = `${nameKey || item.dataKey || "value"}`;
          const itemConfig = config[key];

          return (
            <div
              key={item.value}
              className={cn(
                "flex items-center gap-1.5 [&>svg]:h-3 [&>svg]:w-3 text-muted-foreground"
              )}
            >
              {itemConfig?.icon && !hideIcon ? (
                <itemConfig.icon />
              ) : (
                !hideIcon && (
                  <div
                    className="h-2 w-2 shrink-0 border-2 border-foreground"
                    style={{ backgroundColor: item.color }}
                  />
                )
              )}
              {itemConfig?.label}
            </div>
          );
        })}
    </div>
  );
}

export {
  ChartContainer,
  ChartTooltip,
  ChartLegend,
  ChartLegendContent,
  ChartStyle,
};

"use client";

import * as React from "react";
import { flexRender, type ColumnDef } from "@tanstack/react-table";
import { ChevronLeft, ChevronRight } from "lucide-react";
import { PixelButton } from "./button";
import {
  PixelSelect,
  PixelSelectContent,
  PixelSelectItem,
  PixelSelectTrigger,
  PixelSelectValue,
} from "./select";
import {
  PixelTable,
  PixelTableBody,
  PixelTableCell,
  PixelTableHead,
  PixelTableHeader,
  PixelTableRow,
} from "./table";

interface DataTableProps<TData> {
  // TanStack v9 Table type takes two generics and pulls in a large feature
  // union; a structural `any` here keeps the component usable with any
  // feature set the consumer enables (pagination, sorting, etc.).
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  table: any;
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  columns: ColumnDef<any, any>[];
}

export function PixelDataTable<TData>({
  table,
  columns,
}: DataTableProps<TData>) {
  return (
    <div
      data-slot="data-table"
      className="space-y-4 font-[family-name:var(--pixel-font)]"
    >
      <PixelTable>
        <PixelTableHeader>
          {table.getHeaderGroups().map((headerGroup: { id: string; headers: Array<{ id: string; isPlaceholder: boolean; column: { columnDef: { header?: unknown } }; getContext: () => unknown }> }) => (
            <PixelTableRow key={headerGroup.id}>
              {headerGroup.headers.map((header) => (
                <PixelTableHead key={header.id}>
                  {header.isPlaceholder
                    ? null
                    : flexRender(
                        header.column.columnDef.header as never,
                        header.getContext() as never
                      )}
                </PixelTableHead>
              ))}
            </PixelTableRow>
          ))}
        </PixelTableHeader>
        <PixelTableBody>
          {table.getRowModel().rows?.length ? (
            table.getRowModel().rows.map((row: { id: string; getIsSelected: () => boolean; getVisibleCells: () => Array<{ id: string; column: { columnDef: { cell?: unknown } }; getContext: () => unknown }> }) => (
              <PixelTableRow
                key={row.id}
                data-state={row.getIsSelected() && "selected"}
              >
                {row.getVisibleCells().map((cell) => (
                  <PixelTableCell key={cell.id}>
                    {flexRender(
                      cell.column.columnDef.cell as never,
                      cell.getContext() as never
                    )}
                  </PixelTableCell>
                ))}
              </PixelTableRow>
            ))
          ) : (
            <PixelTableRow>
              <PixelTableCell colSpan={columns.length} className="h-24 text-center">
                No results.
              </PixelTableCell>
            </PixelTableRow>
          )}
        </PixelTableBody>
      </PixelTable>

      <div className="flex items-center justify-between px-2">
        <div className="flex-1 text-xs text-muted-foreground">
          {table.getFilteredSelectedRowModel().rows.length} of{" "}
          {table.getFilteredRowModel().rows.length} row(s) selected.
        </div>
        <div className="flex items-center gap-4">
          <div className="flex items-center gap-2">
            <span className="text-xs">Rows per page</span>
            <PixelSelect
              value={`${table.getState().pagination.pageSize}`}
              onValueChange={(value) => table.setPageSize(Number(value))}
            >
              <PixelSelectTrigger className="h-8 w-[70px]">
                <PixelSelectValue placeholder={table.getState().pagination.pageSize} />
              </PixelSelectTrigger>
              <PixelSelectContent side="top">
                {[10, 20, 30, 40, 50].map((pageSize) => (
                  <PixelSelectItem key={pageSize} value={`${pageSize}`}>
                    {pageSize}
                  </PixelSelectItem>
                ))}
              </PixelSelectContent>
            </PixelSelect>
          </div>
          <div className="flex w-[100px] items-center justify-center text-xs">
            Page {table.getState().pagination.pageIndex + 1} of{" "}
            {table.getPageCount()}
          </div>
          <div className="flex items-center gap-1">
            <PixelButton
              variant="outline"
              size="icon"
              className="h-8 w-8"
              onClick={() => table.previousPage()}
              disabled={!table.getCanPreviousPage()}
            >
              <ChevronLeft className="h-4 w-4" strokeWidth={3} />
            </PixelButton>
            <PixelButton
              variant="outline"
              size="icon"
              className="h-8 w-8"
              onClick={() => table.nextPage()}
              disabled={!table.getCanNextPage()}
            >
              <ChevronRight className="h-4 w-4" strokeWidth={3} />
            </PixelButton>
          </div>
        </div>
      </div>
    </div>
  );
}

